#!/usr/bin/env node
// scripts/seed-data/import-hubspot.mjs
//
// Loads the synthetic seed dataset (scripts/seed-data/output/{companies,contacts}.csv,
// generated by `npm run seed:generate`) into the HubSpot "Vieira GTM Lab" portal via the CRM
// Objects API (batch upsert), then associates each contact with its company.
//
// Deliberately does NOT touch usage-events.csv — that file feeds the Phase 3 Postgres-backed
// reporting/health-score cases, not a CRM object. See README.md.
//
// Auth: reads HUBSPOT_PRIVATE_APP_TOKEN from the environment. Run via
//   npm run import:hubspot
// which wires `node --env-file-if-exists=.env` so the token comes from the project's
// gitignored .env file — never from a shell rc file, never pasted into chat. Required scopes:
//   crm.objects.contacts.read, crm.objects.contacts.write,
//   crm.objects.companies.read, crm.objects.companies.write
// See README.md for exactly where to create the private app and grant these scopes.
//
// Idempotent: uses the batch/upsert endpoint with idProperty=domain (companies) and
// idProperty=email (contacts), so re-running after a re-seed updates existing records instead
// of creating duplicates.
//
// API surface verified live against developers.hubspot.com on 2026-07-24. HubSpot's CRM API
// has moved to a dated version path (2026-03) that supersedes the older /crm/v3/... paths,
// which are now documented under a separate "legacy" section of the docs:
//   POST /crm/objects/2026-03/companies/batch/upsert
//   POST /crm/objects/2026-03/contacts/batch/upsert
//   POST /crm/associations/2026-03/contacts/companies/batch/associate/default
// batch/upsert and batch/create for companies are not spelled out in HubSpot's narrative
// "Companies" guide page (only batch/read is documented there — the "Contacts" guide page is
// more complete and does document batch/upsert), so both routes were confirmed live instead of
// assumed: an unauthenticated POST to each returns 401 (route exists, auth required) rather
// than 404 (route doesn't exist) — the same signature as the documented, known-good
// companies/batch/read endpoint used as a control.

import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { parseCsv } from './lib/csv.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUTPUT_DIR = join(__dirname, 'output');
const API_BASE = 'https://api.hubapi.com';
const API_VERSION = '2026-03';
const BATCH_SIZE = 100; // HubSpot batch operation limit (Contacts guide, "Limits" section)

const TOKEN = process.env.HUBSPOT_PRIVATE_APP_TOKEN;

function fail(message) {
  console.error(`\nERROR: ${message}\n`);
  process.exit(1);
}

if (!TOKEN) {
  fail(
    'HUBSPOT_PRIVATE_APP_TOKEN is not set.\n' +
      '  1. Copy .env.example to .env (chmod 600) and fill in the token.\n' +
      '  2. Run: npm run import:hubspot\n' +
      'See scripts/seed-data/README.md for how to create the private app and required scopes.'
  );
}

function readCsvOrFail(filename) {
  const path = join(OUTPUT_DIR, filename);
  if (!existsSync(path)) {
    fail(`${path} is missing. Run "npm run seed:generate" first.`);
  }
  return parseCsv(readFileSync(path, 'utf8'));
}

function chunk(array, size) {
  const chunks = [];
  for (let i = 0; i < array.length; i += size) chunks.push(array.slice(i, i + size));
  return chunks;
}

async function hubspotRequest(path, body) {
  const res = await fetch(`${API_BASE}${path}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    json = { raw: text };
  }
  if (!res.ok) {
    return { ok: false, status: res.status, error: json };
  }
  return { ok: true, status: res.status, data: json };
}

async function upsertBatch(objectType, inputs) {
  const results = [];
  const errors = [];
  for (const batch of chunk(inputs, BATCH_SIZE)) {
    const res = await hubspotRequest(`/crm/objects/${API_VERSION}/${objectType}/batch/upsert`, {
      inputs: batch,
    });
    if (!res.ok) {
      console.error(`  Batch of ${batch.length} ${objectType} FAILED (HTTP ${res.status}):`);
      console.error(`  ${JSON.stringify(res.error)}`);
      errors.push(...batch.map((input) => ({ id: input.id, error: res.error })));
      continue;
    }
    results.push(...(res.data.results || []));
  }
  return { results, errors };
}

async function associateContactsToCompanies(pairs) {
  const errors = [];
  let associated = 0;
  for (const batch of chunk(pairs, BATCH_SIZE)) {
    const res = await hubspotRequest(
      `/crm/associations/${API_VERSION}/contacts/companies/batch/associate/default`,
      {
        inputs: batch.map(({ contactId, companyId }) => ({
          from: { id: contactId },
          to: { id: companyId },
        })),
      }
    );
    if (!res.ok) {
      console.error(`  Association batch of ${batch.length} FAILED (HTTP ${res.status}):`);
      console.error(`  ${JSON.stringify(res.error)}`);
      errors.push(...batch);
      continue;
    }
    associated += batch.length;
  }
  return { associated, errors };
}

async function main() {
  const companies = readCsvOrFail('companies.csv');
  const contacts = readCsvOrFail('contacts.csv');

  console.log(
    `Importing ${companies.length} companies and ${contacts.length} contacts into HubSpot ("Vieira GTM Lab").`
  );
  console.log(
    'Skipping usage-events.csv by design — it belongs to the Phase 3 reporting cases, not a CRM object.\n'
  );

  console.log('Upserting companies (idProperty=domain)...');
  const companyInputs = companies.map((c) => ({
    idProperty: 'domain',
    id: c.domain,
    properties: {
      name: c.name,
      domain: c.domain,
      industry: c.industry,
      numberofemployees: c.employee_count,
      country: c.country,
    },
  }));
  const companyResult = await upsertBatch('companies', companyInputs);
  console.log(
    `  Companies: ${companyResult.results.length} upserted, ${companyResult.errors.length} errors.`
  );

  console.log('Upserting contacts (idProperty=email)...');
  const contactInputs = contacts.map((c) => ({
    idProperty: 'email',
    id: c.email,
    properties: {
      email: c.email,
      firstname: c.first_name,
      lastname: c.last_name,
      jobtitle: c.job_title,
      lifecyclestage: c.lifecycle_stage,
    },
  }));
  const contactResult = await upsertBatch('contacts', contactInputs);
  console.log(
    `  Contacts: ${contactResult.results.length} upserted, ${contactResult.errors.length} errors.`
  );

  // Build domain -> companyId and email -> contactId maps from the upsert responses so the
  // association step doesn't need a second round-trip to look records up.
  const companyIdByDomain = new Map();
  for (const r of companyResult.results) {
    const domain = r.properties?.domain;
    if (domain) companyIdByDomain.set(domain, r.id);
  }
  const contactIdByEmail = new Map();
  for (const r of contactResult.results) {
    const email = r.properties?.email;
    if (email) contactIdByEmail.set(email, r.id);
  }

  console.log('Associating contacts with their company (unlabeled default association)...');
  const pairs = [];
  const unresolvable = [];
  for (const c of contacts) {
    const contactId = contactIdByEmail.get(c.email);
    const companyId = companyIdByDomain.get(c.company_domain);
    if (!contactId || !companyId) {
      unresolvable.push({ email: c.email, domain: c.company_domain, contactId, companyId });
      continue;
    }
    pairs.push({ contactId, companyId });
  }
  const assocResult = await associateContactsToCompanies(pairs);
  console.log(
    `  Associations: ${assocResult.associated} created, ${assocResult.errors.length} errors, ${unresolvable.length} skipped (missing company or contact id).`
  );
  if (unresolvable.length) {
    console.log('  Skipped pairs (first 5):', unresolvable.slice(0, 5));
  }

  console.log('\nSummary:');
  console.log(`  Companies:    ${companyResult.results.length} created/updated, ${companyResult.errors.length} errors`);
  console.log(`  Contacts:     ${contactResult.results.length} created/updated, ${contactResult.errors.length} errors`);
  console.log(`  Associations: ${assocResult.associated} created, ${assocResult.errors.length} errors`);

  const hadErrors = companyResult.errors.length || contactResult.errors.length || assocResult.errors.length;
  if (hadErrors) {
    console.error('\nCompleted with errors — see per-batch output above.');
    process.exit(1);
  }
  console.log('\nHubSpot import complete. Run "npm run verify:imports" to confirm.');
}

main().catch((err) => {
  console.error('Unexpected failure:', err);
  process.exit(1);
});
